// Stale Task Watchdog — extended to cover in_progress, product_review, released, completed
// Sends to Telegram on stale detection
const SK = $env.SUPABASE_SERVICE_ROLE_KEY;
const SUPA = '${NEXT_PUBLIC_SUPABASE_URL}';
const h = { apikey: SK, Authorization: 'Bearer ' + SK };
const TRIGGER_URL = 'http://127.0.0.1:8787/trigger-agent';

const now = Date.now();

// Thresholds per status (in hours)
const THRESHOLDS = {
  in_progress: 2,        // Builder/agent stuck working > 2h
  product_review: 4,     // Reviewer not acting > 4h
  released: 24,          // Auditor hasn't confirmed > 24h
  completed: 48,         // Hasn't been closed > 48h
};

const issues = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?status=in.(in_progress,product_review,released,completed)&select=id,task_key,title,status,assignee,updated_at,reviewer',
  headers: h
});

if (!Array.isArray(issues) || !issues.length) return [{ json: { action: 'idle' } }];

const staleByStatus = {};
for (const issue of issues) {
  const threshold = THRESHOLDS[issue.status];
  if (!threshold) continue;
  const age = (now - new Date(issue.updated_at)) / (1000 * 60 * 60); // hours
  if (age >= threshold) {
    if (!staleByStatus[issue.status]) staleByStatus[issue.status] = [];
    staleByStatus[issue.status].push({ ...issue, age_hours: Math.round(age) });
  }
}

const statusLabels = {
  in_progress: '🔧 In Progress (>2h)',
  product_review: '👁 Product Review (>4h — needs pass/fail)',
  released: '🚀 Released (>24h — needs audit/close)',
  completed: '✔️ Completed (>48h — needs close)',
};

const alerts = [];
let totalStale = 0;

for (const [status, items] of Object.entries(staleByStatus)) {
  if (!items.length) continue;
  totalStale += items.length;
  const label = statusLabels[status] || status;
  let section = `\n*${label}:*`;
  for (const i of items.slice(0, 3)) {
    section += `\n  • ${i.task_key} ${i.title.slice(0, 45)} — ${i.age_hours}h`;

    // Auto-trigger the responsible agent
    const agentId = i.assignee || (status === 'released' ? 'auditor' : status === 'completed' ? 'auditor' : null);
    if (agentId && agentId !== 'michael') {
      const msg = `Issue ${i.task_key} has been in ${status} for ${i.age_hours}h with no update. Please take action: ${i.title}`;
      try {
        await helpers.httpRequest({
          method: 'POST', url: TRIGGER_URL,
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ agentId, message: msg })
        });
        section += ` → *${agentId} triggered*`;
      } catch(e) {}
    }
  }
  if (items.length > 3) section += `\n  • ...+${items.length - 3} more`;
  alerts.push(section);
}

if (!alerts.length) return [{ json: { action: 'idle', checked: issues.length } }];

const text = `⚠️ *Stale Issue Alert — ${totalStale} issue(s) need attention*${alerts.join('')}\n\n📊 [Mission Control](https://kaos.nabit.work)`;
return [{ json: { text, stale_count: totalStale } }];
